   grid.CellContentClick+=async(a,b)=>{if(b.RowIndex<0||b.ColumnIndex<5)return;var row=grid.Rows[b.RowIndex];row.Selected=true;if(b.ColumnIndex==5){if(server){if(RowConnected(row))await Work(StopShare);else NavigatePage(1);}else{var p=Selected() as StorageConnection;if(p!=null)await Work(!p.Verified?(Func<Task>)EditSelected:RowConnected(row)?(Func<Task>)PauseSelected:Reconnect);}}else if(b.ColumnIndex==6){if(server)NavigatePage(1);else if(!RowConnected(row))await Work(EditSelected);}else if(b.ColumnIndex==7){if(server)await Work(()=>{var p=Selected() as NasProfile;if(p!=null)Process.Start("explorer.exe",Core.Quote(p.Folder));return Task.FromResult(0);});else if(RowConnected(row))await Work(OpenSelected);}else if(b.ColumnIndex==8){if(server){if(!RowConnected(row))await Work(RemoveShare);}else await Work(RemoveSelected);}};
