  private void PaintTableCell(object sender,DataGridViewCellPaintingEventArgs e){
   if(e.RowIndex<0)return;e.PaintBackground(e.ClipBounds,true);var row=grid.Rows[e.RowIndex];bool connected=RowConnected(row);float scale=DeviceDpi/96f;int pad=(int)(12*scale);var bounds=e.CellBounds;Color status=connected?Color.FromArgb(88,199,150):Color.FromArgb(222,176,90);
   if(e.ColumnIndex==0){var connection=row.Tag as StorageConnection;using(var icon=SuiteGlyph.Provider(connection==null?"smb":connection.Provider,(int)(48*scale)))e.Graphics.DrawImage(icon,bounds.X+pad,bounds.Y+(bounds.Height-icon.Height)/2);int x=bounds.X+(int)(76*scale);var area=new Rectangle(x,bounds.Y+(int)(15*scale),bounds.Right-x-pad,(int)(24*scale));using(var font=new Font("Segoe UI",11,FontStyle.Bold))TextRenderer.DrawText(e.Graphics,Convert.ToString(row.Cells[0].Value),font,area,SuiteTheme.Ink,TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);area.Y+=(int)(27*scale);area.Height=(int)(18*scale);TextRenderer.DrawText(e.Graphics,Convert.ToString(row.Cells[1].Value)+" · "+Convert.ToString(row.Cells[2].Value),e.CellStyle.Font,area,SuiteTheme.Muted,TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);area.Y+=(int)(19*scale);TextRenderer.DrawText(e.Graphics,Convert.ToString(row.Cells[3].Value),e.CellStyle.Font,area,status,TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis);if(row.Selected)using(var pen=new Pen(SuiteTheme.Blue,3*scale))e.Graphics.DrawLine(pen,bounds.X+2,bounds.Y+12,bounds.X+2,bounds.Bottom-12);}
   else if(e.ColumnIndex==4){string[] parts=Convert.ToString(e.FormattedValue).Split(new[]{" · "},StringSplitOptions.None);TextRenderer.DrawText(e.Graphics,parts[0],e.CellStyle.Font,new Rectangle(bounds.X+(int)(8*scale),bounds.Y+(int)(18*scale),bounds.Width-(int)(16*scale),(int)(24*scale)),SuiteTheme.Ink,TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis);if(parts.Length>1)TextRenderer.DrawText(e.Graphics,parts[1],e.CellStyle.Font,new Rectangle(bounds.X+(int)(8*scale),bounds.Y+(int)(57*scale),bounds.Width-(int)(16*scale),(int)(22*scale)),SuiteTheme.Muted,TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis);var value=row.Cells[4].Tag;double ratio=value is double?(double)value:-1;if(ratio>=0){var track=new Rectangle(bounds.X+(int)(8*scale),bounds.Y+(int)(47*scale),bounds.Width-(int)(20*scale),(int)(5*scale));using(var bg=new SolidBrush(SuiteTheme.Border))e.Graphics.FillRectangle(bg,track);track.Width=(int)(track.Width*Math.Max(0,Math.Min(1,ratio)));using(var fill=new SolidBrush(ratio>.9?Color.FromArgb(226,151,77):SuiteTheme.Blue))e.Graphics.FillRectangle(fill,track);}}
   else if(e.ColumnIndex>=5){string glyph=e.ColumnIndex==5?(connected?"stop":"play"):e.ColumnIndex==6?"settings":e.ColumnIndex==7?"folder":"trash";bool enabled=e.ColumnIndex==6?server||!connected:e.ColumnIndex==7?server||connected:e.ColumnIndex==8?!server||!connected:true;Color color=!enabled?SuiteTheme.Border:e.ColumnIndex==5?status:e.ColumnIndex==8?Color.FromArgb(218,121,134):SuiteTheme.Muted;using(var icon=SuiteGlyph.Image(glyph,(int)(22*scale),color))e.Graphics.DrawImage(icon,bounds.X+(bounds.Width-icon.Width)/2,bounds.Y+(bounds.Height-icon.Height)/2);}
   using(var line=new Pen(SuiteTheme.Background,4*scale))e.Graphics.DrawLine(line,bounds.Left,bounds.Bottom-2,bounds.Right,bounds.Bottom-2);e.Handled=true;
  }
