  private void BuildServerCards(){
   leftCard.Height=465;rightCard.Height=465;var body=CardBody(leftCard,"Cấu hình ổ chia sẻ","Chọn một ổ trong danh sách hoặc tạo chia sẻ mới.");Field(body,"Tên chia sẻ",share);Field(body,"Ổ / thư mục trên máy chủ",folder);readOnly.Text="Chỉ cho phép đọc";readOnly.Height=30;body.Controls.Add(readOnly);
   var row=Actions(body);Action(row,"Chọn thư mục",()=>{using(var picker=new FolderBrowserDialog())if(picker.ShowDialog(this)==DialogResult.OK)folder.Text=picker.SelectedPath;return Task.FromResult(0);});Action(row,"Bật chia sẻ NAS",CreateShare,true);
   var manage=Actions(body);Action(manage,"Bỏ lưu NAS",RemoveShare);Action(manage,"Sao chép địa chỉ",()=>{if(selectedShare=="")throw new Exception("Chọn NAS đã lưu trước.");Clipboard.SetText(@"\\"+Environment.MachineName+@"\"+selectedShare);message.Text="Đã sao chép địa chỉ NAS.";return Task.FromResult(0);});
   var accessLink=Actions(body);Action(accessLink,"Tài khoản truy cập",()=>{NavigatePage(2);return Task.FromResult(0);});
   var access=CardBody(rightCard,"Tài khoản truy cập","Dùng tài khoản này trên CYAN NAS CLIENT.");Field(access,"Tài khoản Windows / NAS",user);password.UseSystemPasswordChar=true;Field(access,"Mật khẩu NAS",password);createUser.Text="Tạo tài khoản NAS riêng";createUser.Height=30;access.Controls.Add(createUser);
   var pw=Actions(access);Action(pw,"Hiện / Ẩn",()=>{if(password.UseSystemPasswordChar&&password.Text=="")password.Text=nas.LoadPassword(user.Text.Trim());password.UseSystemPasswordChar=!password.UseSystemPasswordChar;return Task.FromResult(0);});Action(pw,"Lưu mật khẩu",()=>{nas.SavePassword(user.Text.Trim(),password.Text);password.Clear();message.Text="Đã lưu mật khẩu mã hóa. Mật khẩu Windows chưa đổi.";return Task.FromResult(0);},true);
   var check=Actions(access);Action(check,"Kiểm tra mật khẩu",async()=>{await Task.Run(()=>NasService.CheckLocalPassword(user.Text.Trim(),Secret()));message.Text="Windows chấp nhận mật khẩu này.";});Action(check,"Đặt lại mật khẩu",async()=>{if(SuiteNotice.Show(this,"Đổi mật khẩu Windows của tài khoản NAS riêng do tool tạo?","Đặt lại mật khẩu",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;await nas.Admin("SetNasPassword",Profile(),password.Text);password.Clear();});var back=Actions(access);Action(back,"Cấu hình chia sẻ",()=>{NavigatePage(1);return Task.FromResult(0);});user.TextChanged+=(a,b)=>{password.Clear();password.UseSystemPasswordChar=true;};NewShare();
