  private string Secret(){return password.Text==""?nas.LoadPassword(user.Text.Trim()):password.Text;}
  private NasProfile Profile(){return new NasProfile{Folder=folder.Text.Trim(),Share=share.Text.Trim(),User=user.Text.Trim(),ReadOnly=readOnly.Checked,CreateUser=createUser.Checked};}
  private void NewShare(){if(settingsPage!=null)NavigatePage(1);creatingShare=true;grid.ClearSelection();selectedShare="";share.Text="CYANNAS";folder.Clear();user.Text="nasuser";password.Clear();createUser.Checked=true;share.Enabled=folder.Enabled=readOnly.Enabled=user.Enabled=createUser.Enabled=true;if(enable!=null){enable.Enabled=true;enable.Text="Bật chia sẻ NAS";}message.Text="Chia sẻ mới · Chọn thư mục và tài khoản NAS.";}
  private async Task CreateShare(){var p=Profile();if(NasService.ReadShareState(p.Share).State!="Stopped")throw new Exception("Tên NAS đã tồn tại hoặc chưa kiểm tra được. Chọn tên mới.");await nas.Admin("Create",p,password.Text);nas.RememberShare(p);if(password.Text!="")nas.SavePassword(p.User,password.Text);password.Clear();selectedShare=p.Share;creatingShare=false;await RefreshData();NavigatePage(0);message.Text="Đã bật NAS · Máy khác có thể truy cập qua Tailscale.";}
  private async Task RemoveShare(){var p=Selected() as NasProfile;if(p==null)throw new Exception("Chọn NAS trong danh sách.");if(NasService.ReadShareState(p.Share).State!="Stopped")throw new Exception("Dừng NAS trước khi bỏ cấu hình. File không bị xóa.");if(SuiteNotice.Show(this,"Bỏ cấu hình "+p.Share+"? File và tài khoản vẫn được giữ.","Bỏ lưu NAS",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;nas.ForgetShare(p.Share);NewShare();await RefreshData();}
  private async Task StopShare(){var p=Selected() as NasProfile;if(p==null)throw new Exception("Chọn NAS trong danh sách.");await nas.Admin("Remove",p);await RefreshData();}
  private object Selected(){return grid.SelectedRows.Count==0?null:grid.SelectedRows[0].Tag;}
  private void SelectRow(){if(rebindingRows)return;if(grid.SelectedRows.Count==0)return;var selected=grid.SelectedRows[0].Tag;if(server){var p=selected as NasProfile;if(p==null)return;creatingShare=false;capacity.Text=CapacityInfo.Local(p.Folder);if(selectedShare!=p.Share){share.Text=p.Share;folder.Text=p.Folder;user.Text=p.User;readOnly.Checked=p.ReadOnly;createUser.Checked=false;}selectedShare=p.Share;var active=states.ContainsKey(p.Share)&&states[p.Share].State=="Enabled";share.Enabled=folder.Enabled=readOnly.Enabled=user.Enabled=createUser.Enabled=!active;if(enable!=null){enable.Enabled=!active;enable.Text=active?"Đã bật chia sẻ":"Bật chia sẻ NAS";}if(stop!=null)stop.Enabled=active;}else{var p=selected as StorageConnection;if(p!=null){var r=engine.Runtime(p);capacity.Text=r.Capacity;if(connectionInfo!=null)connectionInfo.Text=p.Name+" · "+p.Letter+":\n\n"+StorageProviders.Find(p.Provider).Name+"\nThư mục gốc: "+p.Path+"\nTrạng thái: "+r.State+"\nDung lượng: "+r.Capacity+"\nTự kết nối: "+(p.AutoConnect?"Bật":"Tắt");message.Text=p.Name+" · "+StorageProviders.Find(p.Provider).Name+" · "+r.State+(r.Message==""?"":" · "+r.Message);}}}
  private void BuildClientCards(){var body=CardBody(leftCard,"Kết nối đang chọn","Chọn dòng trong danh sách để chỉnh sửa hoặc mở ổ.");connectionInfo=Label("NAS · máy chủ · cloud\n\nMỗi nguồn có đăng nhập, cache và ký tự ổ riêng.\n\nFTP · FTPS · SFTP · WebDAV · S3 · B2\nDropbox · OneDrive · Google Drive\nAzure Blob · Azure Files · Google Cloud Storage",10);connectionInfo.Height=172;body.Controls.Add(connectionInfo);var row=Actions(body);Action(row,"Chỉnh sửa",EditSelected);Action(row,"Kết nối lại",Reconnect,true);var manage=Actions(body);Action(manage,"Tạm ngắt",PauseSelected);Action(manage,"Bỏ lưu",RemoveSelected);
   var auto=CardBody(rightCard,"Kết nối tự động","Thông tin đăng nhập được mã hóa theo tài khoản Windows.");var reconnect=new SuiteCheckBox{Text="Phục hồi sau đổi Wi-Fi / máy thức dậy",Checked=true,Enabled=false,AutoSize=true,Height=38};auto.Controls.Add(reconnect);var note=Label("Chỉ tự kết nối các cấu hình đã kiểm tra và được bật.\n\nỔ Tạm ngắt giữ nguyên trạng thái qua lần khởi động sau.\n\nĐổi mạng không cưỡng chế dừng VFS hay bỏ dữ liệu chờ upload.",9);note.ForeColor=SuiteTheme.Muted;note.Height=150;auto.Controls.Add(note);
