  private async Task AddConnection(){using(var dialog=new StorageDialog(engine))if(dialog.ShowDialog(this)==DialogResult.OK){await RefreshData();}}
  private async Task EditSelected(){var p=Selected() as StorageConnection;if(p==null)throw new Exception("Chọn kết nối cần sửa.");var r=engine.Runtime(p);if((r.Job!=null&&!r.Job.IsCompleted)||(r.Service!=null&&r.Service.Running)||r.Native)throw new Exception("Tạm ngắt ổ trước khi chỉnh sửa cấu hình.");using(var dialog=new StorageDialog(engine,p))if(dialog.ShowDialog(this)==DialogResult.OK)await RefreshData();}
  private async Task Reconnect(){var p=Selected() as StorageConnection;if(p==null)throw new Exception("Chọn kết nối.");p.AutoConnect=true;engine.Store.Put(p);await engine.Connect(p);await RefreshData();}
  private async Task PauseSelected(){var p=Selected() as StorageConnection;if(p==null)throw new Exception("Chọn kết nối.");await engine.Stop(p);await RefreshData();}
  private async Task RemoveSelected(){var p=Selected() as StorageConnection;if(p==null)throw new Exception("Chọn kết nối.");if(SuiteNotice.Show(this,"Bỏ cấu hình "+p.Name+"? File và cache được giữ lại.","Bỏ lưu",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;await engine.Stop(p);var values=engine.Store.Load();values.RemoveAll(x=>x.Id==p.Id);engine.Store.Save(values);await RefreshData();}
  private Task OpenSelected(){var p=Selected() as StorageConnection;if(p==null)throw new Exception("Chọn kết nối.");if(engine.Runtime(p).State!="Đã kết nối")throw new Exception("Ổ chưa sẵn sàng. Bấm Kết nối lại để kiểm tra.");Process.Start("explorer.exe",Core.Quote(p.Letter+@":\"));return Task.FromResult(0);}
  private async Task RefreshData(){if(preview)return;if(DateTime.UtcNow>=nextNetwork){nextNetwork=DateTime.UtcNow.AddMinutes(1);try{var net=await nas.Status();network.Text=net.Ready?"Tailscale · "+net.Address:net.State=="NotInstalled"?"Chưa cài Tailscale":"Chưa đăng nhập";}catch{network.Text="Chưa sẵn sàng";}}string key=Selected() is NasProfile?((NasProfile)Selected()).Share:Selected() is StorageConnection?((StorageConnection)Selected()).Id:null;
   if(server){var shares=nas.LocalShares();var checks=await Task.Run(()=>shares.ToDictionary(p=>p.Share,p=>NasService.ReadShareState(p.Share)));rebindingRows=true;states.Clear();foreach(var pair in checks)states[pair.Key]=pair.Value;grid.Rows.Clear();foreach(var p in shares){var state=checks[p.Share];var index=grid.Rows.Add(p.Share,p.ReadOnly?"Chỉ đọc":"Đọc & ghi",p.Folder,state.Message,CapacityInfo.Local(p.Folder),state.State=="Enabled"?"Dừng NAS":"Đã dừng");grid.Rows[index].Tag=p;grid.Rows[index].Cells[4].Tag=CapacityInfo.LocalRatio(p.Folder);if(p.Share==key)grid.Rows[index].Selected=true;}if(creatingShare)grid.ClearSelection();rebindingRows=false;count.Text=checks.Values.Count(x=>x.State=="Enabled")+" / "+shares.Count+" ổ";}
   else{rebindingRows=true;var values=engine.Store.Load();grid.Rows.Clear();foreach(var p in values){var r=engine.Runtime(p);var index=grid.Rows.Add(p.Letter+":  "+p.Name,StorageProviders.Find(p.Provider).Name,p.Get("host")!=""?p.Get("host"):p.Path,!p.Verified?"Chưa xác thực":p.AutoConnect||r.Native||(r.Service!=null&&r.Service.Running)?r.State:"Tạm ngắt",r.Capacity,!p.Verified?"Thiết lập":r.State=="Đã kết nối"?"Ngắt kết nối":"Kết nối");grid.Rows[index].Tag=p;grid.Rows[index].Cells[4].Tag=r.TotalBytes.HasValue&&r.TotalBytes.Value>0&&r.UsedBytes.HasValue?(double)r.UsedBytes.Value/r.TotalBytes.Value:-1;if(p.Id==key)grid.Rows[index].Selected=true;}rebindingRows=false;count.Text=values.Count+" kết nối";}if(!server||!creatingShare)SelectRow();RefreshPageStatus();}
  private async Task Work(Func<Task> action){if(busy||preview)return;busy=true;try{await action();}catch(Exception e){message.Text=e.Message;SuiteNotice.Show(this,e.Message,Text,MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{busy=false;}}
