  internal void NavigatePage(int index){
   if(index<0||index>=pageNames.Count||settingsPage==null)return;
   dashboard.SuspendLayout();content.SuspendLayout();
   activePage=index;heading.Text=pageNames[index];
   string[] descriptions=server?new[]{"Danh sách ổ chia sẻ, trạng thái và dung lượng trên máy chủ.","Chọn ổ ở trang danh sách hoặc tạo chia sẻ mới.","Quản lý tài khoản Windows / NAS dùng trên thiết bị kết nối.","Thiết lập truy cập NAS từ xa bằng Tailscale.","Khởi động cùng Windows, cập nhật và thoát an toàn."}:new[]{"Quản lý NAS, máy chủ và cloud như ổ đĩa Windows.","Thông tin và thao tác cho kết nối được chọn ở trang danh sách.","Theo dõi kết nối và quá trình phục hồi sau khi đổi mạng.","Thiết lập Tailscale để truy cập NAS trên máy khác.","Khởi động, phục hồi kết nối và cập nhật ứng dụng."};
   pageDescription.Text=descriptions[index];
   overviewList.Visible=index==0;overviewSummary.Visible=false;headerActions.Visible=false;
   details.Visible=index==1||(server&&index==2);leftCard.Visible=index==1;
   rightCard.Visible=server?index==2:index==4;networkPage.Visible=index==3;settingsPage.Visible=index==4;activityPage.Visible=!server&&index==2;
   for(int i=0;i<navigation.Count;i++){navigation[i].BackColor=i==index?SuiteTheme.Surface:SuiteTheme.Sidebar;((SuitePageTab)navigation[i]).Active=i==index;navigation[i].Invalidate();navigation[i].ForeColor=i==index?SuiteTheme.Blue:SuiteTheme.Ink;navigation[i].AccessibleDescription=i==index?"Trang đang mở":"Mở trang "+pageNames[i];}
   content.AutoScrollPosition=Point.Empty;RefreshPageStatus();LayoutContent();
   dashboard.ResumeLayout(true);content.ResumeLayout(true);content.AutoScrollPosition=Point.Empty;
  }
  private void RefreshPageStatus(){
   if(networkStatus!=null)networkStatus.Text=network.Text;
   if(activityText!=null&&!server){
    if(preview)activityText.Text=@"NAS · MEDIA     Đã kết nối

Google Drive     Đã kết nối

Project Server     Đang nối lại
Đang chờ máy chủ phản hồi.

Cloud Backup     Đã kết nối

Dữ liệu minh họa";
    else activityText.Text=string.Join("\n\n",engine.Store.Load().Select(p=>p.Letter+":  "+p.Name+" · "+engine.Runtime(p).State+"\n"+engine.Runtime(p).Message)).Replace("\n",Environment.NewLine);
    if(activityText.Text=="")activityText.Text="Chưa có kết nối. Thêm nguồn lưu trữ ở trang Kết nối của tôi.";activityText.Height=Math.Max(300,activityText.Text.Split(new[]{(char)10}).Length*24);
   }
  }
